import { BASE_URL, IS_BILLING_ENABLED } from "../../Config";
import { APIResponse, Page, expect, test } from "@playwright/test";
import URL from "Common/Types/API/URL";

/*
 * The Home service serves the NIP-05 identity document at
 * /.well-known/nostr.json (Home/Routes.ts, generated by Home/Utils/Nostr.ts).
 *
 * Unit tests pin the document itself; this suite is the deployment contract.
 * It proves the route is mounted and reachable through the ingress — a
 * /.well-known path is easy to lose to nginx, which routes several of them
 * elsewhere — that it answers as JSON rather than an HTML error page, and
 * that it carries the open CORS header NIP-05 requires of it (clients fetch
 * it cross-origin from the browser).
 *
 * It also pins the host gate, the same way Robots.spec.ts does: an E2E
 * deployment is never oneuptime.com, so it must publish no names at all
 * rather than claim OneUptime's account for its own domain.
 *
 * These run only where the Home marketing site is deployed, which the suite
 * gates on IS_BILLING_ENABLED like the other Home specs.
 */

test.describe("Home: nostr.json", () => {
  test("serves a NIP-05 document as JSON with an open CORS policy", async ({
    page,
  }: {
    page: Page;
  }) => {
    if (!IS_BILLING_ENABLED) {
      return; // Home marketing site is only deployed in the SaaS stack.
    }

    page.setDefaultNavigationTimeout(120000); // 2 minutes

    const endpoint: string = URL.fromString(BASE_URL.toString())
      .addRoute("/.well-known/nostr.json")
      .toString();

    const response: APIResponse = await page.request.get(endpoint);

    expect(response.status()).toBe(200);
    expect(response.headers()["content-type"] || "").toContain(
      "application/json",
    );
    expect(response.headers()["access-control-allow-origin"]).toBe("*");

    const document: { names?: { [name: string]: string } } =
      await response.json();

    expect(typeof document.names).toBe("object");

    /*
     * The E2E deployment is not the canonical domain, so it publishes nothing.
     * Where it is, "_" maps to the account and the value is a hex key - never
     * the bech32 npub, which NIP-05 does not accept.
     */
    const rootKey: string | undefined = document.names?.["_"];

    if (rootKey) {
      expect(rootKey).toMatch(/^[0-9a-f]{64}$/);
    } else {
      expect(document.names).toEqual({});
    }
  });

  test("answers a name query with only that name", async ({
    page,
  }: {
    page: Page;
  }) => {
    if (!IS_BILLING_ENABLED) {
      return;
    }

    page.setDefaultNavigationTimeout(120000);

    const endpoint: string = URL.fromString(BASE_URL.toString())
      .addRoute("/.well-known/nostr.json")
      .toString();

    const response: APIResponse = await page.request.get(
      `${endpoint}?name=nobody-owns-this-name`,
    );

    expect(response.status()).toBe(200);

    const document: { names?: { [name: string]: string } } =
      await response.json();

    expect(document.names).toEqual({});
  });
});
